<?php
require_once __DIR__.'/../includes/config.php';require_once __DIR__.'/../includes/session.php';if(session_status()===PHP_SESSION_NONE)session_start();if(empty($_SESSION['rider_id'])){header('Location:rider-login.php');exit;}$rid=(int)$_SESSION['rider_id'];function ph($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}$msg='';$err='';
if($_SERVER['REQUEST_METHOD']==='POST'){$name=trim($_POST['full_name']??'');$phone=trim($_POST['phone']??'');$vehicle=trim($_POST['vehicle_type']??'');$bike=trim($_POST['bike_number']??'');if($name===''||$phone==='')$err='Name and phone are required.';else{$st=$conn->prepare("UPDATE riders SET full_name=?,phone=?,vehicle_type=?,bike_number=? WHERE id=?");if($st){$st->bind_param('ssssi',$name,$phone,$vehicle,$bike,$rid);if($st->execute()){$msg='Profile updated successfully.';$_SESSION['rider_name']=$name;}else$err='Could not update profile.';$st->close();}else$err='Database error.';}}
$r=null;$st=$conn->prepare("SELECT full_name,email,phone,cnic,vehicle_type,bike_number,status,created_at FROM riders WHERE id=? LIMIT 1");if($st){$st->bind_param('i',$rid);$st->execute();$r=$st->get_result()->fetch_assoc();$st->close();}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Rider Profile | Humsafar</title><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.2/css/all.min.css"><style>*{box-sizing:border-box}body{margin:0;background:#f7f7f9;font:14px Segoe UI,Arial;color:#222}.page{margin-left:223px;padding:32px;max-width:900px}h1{margin:0;font-size:32px}.sub{color:#777}.card{background:#fff;border:1px solid #eee;border-radius:16px;padding:25px;margin-top:22px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:16px}.field label{display:block;font-weight:800;margin-bottom:7px}.field input{width:100%;padding:12px;border:1px solid #ddd;border-radius:9px}.field input[readonly]{background:#f5f5f5}.btn{margin-top:20px;border:0;border-radius:9px;background:#ed0038;color:#fff;padding:13px 22px;font-weight:800}.flash{padding:12px;border-radius:9px;margin-top:15px}.ok{background:#eaf8ef;color:#18733d}.bad{background:#fff0f2;color:#b0002d}.status{display:inline-block;padding:7px 12px;border-radius:20px;background:#eaf8ef;color:#18733d;font-weight:800}@media(max-width:900px){.page{margin-left:0;padding:20px}.grid{grid-template-columns:1fr}}</style></head><body><?php include __DIR__.'/rider-sidebar.php';?><main class="page"><h1>My Profile</h1><p class="sub">Manage your rider contact and vehicle information.</p><?php if($msg):?><div class="flash ok"><?=ph($msg)?></div><?php endif;?><?php if($err):?><div class="flash bad"><?=ph($err)?></div><?php endif;?><div class="card"><form method="post"><div class="grid"><div class="field"><label>Full Name</label><input name="full_name" value="<?=ph($r['full_name']??'')?>" required></div><div class="field"><label>Phone</label><input name="phone" value="<?=ph($r['phone']??'')?>" required></div><div class="field"><label>Email</label><input value="<?=ph($r['email']??'')?>" readonly></div><div class="field"><label>CNIC</label><input value="<?=ph($r['cnic']??'')?>" readonly></div><div class="field"><label>Vehicle Type</label><input name="vehicle_type" value="<?=ph($r['vehicle_type']??'')?>" placeholder="Bike / Motorcycle"></div><div class="field"><label>Bike Number</label><input name="bike_number" value="<?=ph($r['bike_number']??'')?>" placeholder="ABC-123"></div></div><p style="margin-top:20px">Account Status: <span class="status"><?=ph(ucfirst($r['status']??'pending'))?></span></p><button class="btn" type="submit"><i class="fa-solid fa-save"></i> Save Changes</button></form></div></main></body></html>